/**
 * The parser may pass a plain string or an object with a single
 * `{ key: value }` entry for most attributes.
 */
type ParserAttribute = string | Record<string, string>;

/**
 * The fields a C4 element, boundary or relationship stores as `{ text }`. Everything else
 * a named attribute can set - `$tags`, `$sprite`, `$link`, colours, `$shape` - is a plain
 * string.
 */
const TEXT_FIELDS = new Set(['label', 'descr', 'techn', 'type']);

/**
 * Apply optional C4 attributes to `bag` from the parser.
 *
 * Values may arrive as a raw positional value or a single `{ key: value }` named
 * override; `undefined` is skipped so an earlier-set value is not clobbered.
 */
const assignAttributes = <Bag extends C4Shape | C4Boundary | C4Rel>(
  bag: Bag,
  attrs: Record<string, ParserAttribute | undefined>
): void => {
  for (const [field, value] of Object.entries(attrs)) {
    if (value === undefined) {
      continue;
    }
    if (typeof value === 'object') {
      const [key, val] = Object.entries(value)[0];
      // Same rule as the positional text slots: a text field is stored as `{ text }`
      // whichever slot it arrived through. `System_Boundary` and friends splice their
      // kind in as a positional argument, so an explicit `$type` shifts along into this
      // one and would otherwise land here as a bare string and overwrite the wrapped
      // value the type slot just set.
      bag[key] = TEXT_FIELDS.has(key) ? { text: val } : val;
    } else {
      bag[field] = value;
    }
  }
};

const createGlobalBoundary = (): C4Boundary =>
  ({
    alias: 'global',
    label: { text: 'global' },
    type: { text: 'global' },
    tags: null,
    link: null,
    parentBoundary: '',
    // The layout fields are populated later by the renderer.
  }) as C4Boundary;

let c4ShapeArray: C4Shape[] = [];
let boundaryParseStack = [''];
let currentBoundaryParse = 'global';
let parentBoundaryParse = '';
let boundaries: C4Boundary[] = [createGlobalBoundary()];
let rels: C4Rel[] = [];
let title = '';
let wrapEnabled: boolean | undefined = false;
let c4ShapeInRow = 4;
let c4BoundaryInRow = 2;
let c4Type: string | undefined;

export const getC4Type = function () {
  return c4Type;
};

export const setC4Type = function (c4TypeParam: string) {
  const sanitizedText = sanitizeText(c4TypeParam, getConfig());
  c4Type = sanitizedText;
};

//type, from, to, label, ?techn, ?descr, ?sprite, ?tags, $link
export const addRel = function (
  type: string | null | undefined,
  from: string | null | undefined,
  to: string | null | undefined,
  label: string | null | undefined,
  techn?: ParserAttribute | null,
  descr?: ParserAttribute | null,
  sprite?: ParserAttribute,
  tags?: ParserAttribute,
  link?: ParserAttribute
) {
  // Don't allow label nulling
  if (
    type === undefined ||
    type === null ||
    from === undefined ||
    from === null ||
    to === undefined ||
    to === null ||
    label === undefined ||
    label === null
  ) {
    return;
  }

  let rel = {} as C4Rel;
  const old = rels.find((rel) => rel.from === from && rel.to === to);
  if (old) {
    rel = old;
  } else {
    rels.push(rel);
  }

  rel.type = type;
  rel.from = from;
  rel.to = to;
  rel.label = { text: label };

  if (techn === undefined || techn === null) {
    rel.techn ??= { text: '' };
  } else {
    if (typeof techn === 'object') {
      const [key, value] = Object.entries(techn)[0];
      rel[key] = TEXT_FIELDS.has(key) ? { text: value } : value;
    } else {
      rel.techn = { text: techn };
    }
  }

  if (descr === undefined || descr === null) {
    rel.descr ??= { text: '' };
  } else {
    if (typeof descr === 'object') {
      const [key, value] = Object.entries(descr)[0];
      rel[key] = TEXT_FIELDS.has(key) ? { text: value } : value;
    } else {
      rel.descr = { text: descr };
    }
  }

  assignAttributes(rel, { sprite, tags, link });
  rel.wrap = autoWrap();
};

//type, alias, label, ?descr, ?sprite, ?tags, $link
export const addPersonOrSystem = function (
  typeC4Shape: string,
  alias: string | null,
  label: string | null | undefined,
  descr?: ParserAttribute | null,
  sprite?: ParserAttribute,
  tags?: ParserAttribute,
  link?: ParserAttribute
) {
  // Don't allow label nulling
  if (alias === null || label === null) {
    return;
  }

  let personOrSystem = {} as C4Shape;
  const old = c4ShapeArray.find((personOrSystem) => personOrSystem.alias === alias);
  if (old && alias === old.alias) {
    personOrSystem = old;
  } else {
    personOrSystem.alias = alias;
    c4ShapeArray.push(personOrSystem);
  }

  // Don't allow null labels, either
  if (label === undefined || label === null) {
    personOrSystem.label = { text: '' };
  } else {
    personOrSystem.label = { text: label };
  }

  if (descr === undefined || descr === null) {
    personOrSystem.descr ??= { text: '' };
  } else {
    if (typeof descr === 'object') {
      const [key, value] = Object.entries(descr)[0];
      personOrSystem[key] = TEXT_FIELDS.has(key) ? { text: value } : value;
    } else {
      personOrSystem.descr = { text: descr };
    }
  }

  assignAttributes(personOrSystem, { sprite, tags, link });
  personOrSystem.typeC4Shape = { text: typeC4Shape };
  personOrSystem.parentBoundary = currentBoundaryParse;
  personOrSystem.wrap = autoWrap();
};

